@app.route("/", methods=["GET"])
def index():
    # 旧ルーレットの URL（/?table_id=...）で来た場合はルーレットへ案内する
    legacy_table_id = request.args.get("table_id", "").strip()
    if legacy_table_id:
        return redirect(url_for("roulette", table_id=legacy_table_id))
    categories = {}
    for game in GAMES:
        categories[game["category"]] = categories.get(game["category"], 0) + 1
    enriched = []
    for game in GAMES:
        item = dict(game)
        minutes, level = GAME_META.get(game["slug"], (3, 2))
        item["minutes"] = minutes
        item["level"] = level
        enriched.append(item)
    pickup = dict(_today_pickup())
    p_minutes, p_level = GAME_META.get(pickup["slug"], (3, 2))
    pickup["minutes"] = p_minutes
    pickup["level"] = p_level
    return render_template_string(
        PORTAL_TEMPLATE,
        games=enriched,
        categories=sorted(categories.items()),
        pickup=pickup,
        abs_url=request.url_root,
    )


