FISH_ESCAPE_MS = 1200


def fishing_pick(ms: int) -> int:
    """反応が速いほどレアな魚の重みを上げる抽選。魚のインデックスを返す。"""
    if ms <= 300:
        bonus = 3.0
    elif ms <= 600:
        bonus = 1.8
    else:
        bonus = 1.0
    weights = []
    for fish in FISH_KINDS:
        w = float(fish["weight"])
        if fish["rarity"] in ("レア", "超レア"):
            w *= bonus
        weights.append(w)
    return random.choices(range(len(FISH_KINDS)), weights=weights)[0]


